def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    gcd, x1, y1 = extended_gcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return gcd, x, y

def mod_inverse(a, m):
    gcd, x, _ = extended_gcd(a, m)
    if gcd != 1:
        raise ValueError("Inverse doesn't exist")
    else:
        return x % m

def chinese_remainder_theorem(remainders, moduli):
    total = 0
    prod = 1
    for m in moduli:
        prod *= m
    for rem, mod in zip(remainders, moduli):
        p = prod // mod
        inv = mod_inverse(p, mod)
        total += rem * p * inv
    return total % prod

def solve(inputs: dict) -> float:
    remainders = inputs['REMAINDERS']
    moduli = inputs['MODULI']
    return chinese_remainder_theorem(remainders, moduli)

